import Application, { Item } from "../models/Application";
import ChatService from "../services/ChatService";
import OfferService from "../services/OfferService";
import UserService from "../services/UserService";
const UPDATE_WAIT_TIME = 10000; // 10 seconds
export default class OfferChatPageController {
    constructor(view) {
        // URLSearchParams
        this.urlParams = new URLSearchParams(window.location.search);
        this.chatID = this.urlParams.get("id");
        // Models
        this.application = Application.getInstance();
        this.currentUser = this.application.get(Item.CurrentUser);
        this.model = new Object();
        this.view = view;
        this.initialize();
    }
    async initialize() {
        // Preconditions
        if (!this.currentUser)
            throw new Error("user not connected");
        // URL Parameters
        if (!this.chatID)
            throw new Error("missing chat ID");
        let chat;
        try {
            // Fetch data
            chat = await ChatService.getByID(this.chatID);
            if (!chat)
                throw new Error("chat not found");
            this.model.offer = await OfferService.getByID(chat.offerID);
            if (!this.model.offer)
                throw new Error("offer not found");
            this.model.seller = await UserService.getByID(this.model.offer.sellerID);
            if (!this.model.seller)
                throw new Error("seller not found");
        }
        catch (error) {
            console.error(`Error Fetching data: ${error}`);
            return;
        }
        // Processing data
        for (let i = 0; i < chat.messages.length; i++) {
            const msg = chat.messages[i];
            this.model.chat.messages.push({
                isMine: msg.senderID === this.currentUser._id,
                content: msg.content,
                timestamp: msg.timestamp
            });
        }
        this.connectEvents();
        this.view.create(this.model);
    }
    connectEvents() {
        const messageForm = this.view.querySelector(".message-form");
        messageForm.onsubmit = (event) => this.onSubmitMessage(event);
        if (this.updateInterval)
            clearInterval(this.updateInterval);
        this.updateInterval = setInterval(() => this.keepUpdated(), UPDATE_WAIT_TIME);
    }
    async onSubmitMessage(event) {
        event.preventDefault();
        const form = event.target;
        const formData = new FormData(form);
        const message = formData.get("message");
        await ChatService.sendMessage(this.model.chat._id, message, this.currentUser);
        form.reset();
    }
    async keepUpdated() {
        let newChat;
        try {
            newChat = await ChatService.getByID(this.chatID);
        }
        catch (error) {
            console.error(`Error updating chat: ${error}`);
        }
        const oldMessagesCount = this.model.chat.messages.length;
        const newMessagesCount = newChat.messages.length;
        if (newMessagesCount > oldMessagesCount) {
            const messagesToAdd = newChat.messages.slice(oldMessagesCount).map(msg => {
                return {
                    isMine: msg.senderID === this.currentUser._id,
                    content: msg.content,
                    timestamp: msg.timestamp
                };
            });
            this.view.update(messagesToAdd);
        }
        this.model.chat = {
            _id: newChat._id,
            offerID: newChat.offerID,
            messages: newChat.messages.map(msg => ({
                isMine: msg.senderID === this.currentUser._id,
                content: msg.content,
                timestamp: msg.timestamp
            }))
        };
    }
}
